insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_participant','participant','noun','a person who takes part in an activity or event','[{"senseId":"participant_1","meaning":"a person who takes part in an activity or event","acceptedParaphrases":["person taking part","someone who joins in"],"masteryContexts":[{"contextId":"u3_01_participant_meaning","text":"Each participant in the cooking class received a free recipe book.","meaning":"a person who takes part in an activity","wrongMeanings":["a person who watches an activity","a person who judges an activity","a person who pays for an activity"]},{"contextId":"u3_01_participant_paraphrase","text":"Researchers asked every participant in the food survey to keep a diary.","meaning":"someone who joins in a study or activity","wrongMeanings":["someone who writes about a study or activity","someone who judges a study or activity","someone who funds a study or activity"]}],"situationDistractors":["The audience sat quietly and watched the chef cook on the stage.","The organiser checked the tickets at the door and counted the chairs.","The sponsor paid for the food but did not attend the event.","The photographer stood at the back of the hall and took pictures of the stage.","The head teacher gave a short speech and then handed out the prizes to the winners at the end of the evening.","A neighbour lent the club some tables."],"gapDistractors":[{"contextId":"u3_01_participant_gap_1","answer":"participant","wrong":["spectator","judge","sponsor"]},{"contextId":"u3_01_participant_gap_2","answer":"participant","wrong":["journalist","supplier","inspector"]},{"contextId":"u3_01_participant_gap_3","answer":"participant","wrong":["sponsor","referee","commentator"]}],"spellingErrors":["participent","particpant","partisipant","participaunt","particapant","particiant"],"wordFamilyForms":[{"form":"participant","partOfSpeech":"noun","example":"Every participant in the quiz received a small prize.","pedagogicallyUseful":true},{"form":"participate","partOfSpeech":"verb","example":"Students are encouraged to participate in at least one school club.","pedagogicallyUseful":true,"altExample":"Adults and children can both participate in the weekend cooking workshop."},{"form":"participation","partOfSpeech":"noun","example":"Active participation in class helps students remember new vocabulary.","pedagogicallyUseful":true,"altExample":"Parents were thanked for their participation in the school food festival."}],"masteryPassages":[{"passageId":"u3_01_participant_passage_1","contextId":"u3_01_participant_gap_1","text":"The cooking competition attracted forty people from different schools. Every ____ had to prepare a three-course meal in just two hours.","answer":"participant"},{"passageId":"u3_01_participant_passage_2","contextId":"u3_01_participant_gap_2","text":"Researchers wanted to learn about teenage eating habits. Each ____ in the survey was asked to write down everything eaten for seven days.","answer":"participant"}],"contextDependentParaphrases":[],"wrongParaphrases":["person watching an event","person running an event","person paying for an event"],"misleadingDistractors":["a person who watches an event","a person who organises an event","a person who pays for an event"]}]'::jsonb,'["participate","participation"]'::jsonb,'["active participant","willing participant","study participant"]'::jsonb,'live'),
('vocab_outlet','outlet','noun','a place, such as a shop or restaurant, where a company sells its products','[{"senseId":"outlet_1","meaning":"a place, such as a shop or restaurant, where a company sells its products","acceptedParaphrases":["shop or restaurant","place that sells products"],"masteryContexts":[{"contextId":"u3_02_outlet_meaning","text":"There is a new coffee outlet opposite the school gates.","meaning":"a place where a company sells its products","wrongMeanings":["a place where a company makes its products","a place where a company stores its products","a place where a company advertises its products"]},{"contextId":"u3_02_outlet_paraphrase","text":"Each outlet in the chain serves the same menu at the same prices.","meaning":"one shop or restaurant belonging to a larger company","wrongMeanings":["one office belonging to a larger company","one factory belonging to a larger company","one farm belonging to a larger company"]}],"situationDistractors":["The factory produced thousands of sandwiches every morning and sent them away in vans.","The company’s head office is in London and employs three hundred managers.","A food blogger reviewed the new menu on her website.","The farmer sold his vegetables from a stall at the weekly market in the village square.","The chef wrote a new recipe for tomato soup.","The cooking oil was delivered to the factory by lorry every Monday morning before the workers arrived."],"gapDistractors":[{"contextId":"u3_02_outlet_gap_1","answer":"outlet","wrong":["factory","office","farm"]},{"contextId":"u3_02_outlet_gap_2","answer":"outlet","wrong":["recipe","menu","customer"]},{"contextId":"u3_02_outlet_gap_3","answer":"outlet","wrong":["recipe","loaf","delivery"]}],"spellingErrors":["outlett","outlit","autlet","outlat","outlete","outlt"],"masteryPassages":[{"passageId":"u3_02_outlet_passage_1","contextId":"u3_02_outlet_gap_1","text":"The company began with one small cafe in Leeds. Today it has more than two hundred branches, and a new ____ opens in a different town almost every month.","answer":"outlet"},{"passageId":"u3_02_outlet_passage_2","contextId":"u3_02_outlet_gap_2","text":"Most of the bakery’s bread goes to supermarkets. However, the company also owns a small retail ____ on the high street.","answer":"outlet"}],"contextDependentParaphrases":[],"wrongParaphrases":["farm or factory","office or bank","school or hospital"],"misleadingDistractors":["a plug socket for electrical equipment","a pipe that carries water away","a way of expressing strong feelings"]}]'::jsonb,'[]'::jsonb,'["food outlet","retail outlet","local outlet"]'::jsonb,'live'),
('vocab_sprinkled','sprinkled','verb','scattered small pieces or drops of something lightly over a surface','[{"senseId":"sprinkled_1","meaning":"scattered small pieces or drops of something lightly over a surface","acceptedParaphrases":["scattered","spread lightly"],"masteryContexts":[{"contextId":"u3_03_sprinkled_meaning","text":"She sprinkled grated cheese over the pasta before putting it under the grill.","meaning":"scattered small pieces over something","wrongMeanings":["poured a thick liquid over something","wrapped a thin layer around something","removed small pieces from something"]},{"contextId":"u3_03_sprinkled_paraphrase","text":"The waiter sprinkled a little salt on the chips and handed them over.","meaning":"shook small amounts onto something","wrongMeanings":["spilled a large amount onto something","rubbed oil firmly into something","wiped dust carefully off something"]}],"situationDistractors":["The cook poured the whole bottle of oil into the pan at once.","He wrapped the sandwiches tightly in paper and put them in his bag.","She mixed the flour and eggs together in a large bowl.","He stirred the sauce slowly until it became thick and smooth.","The cook placed the whole fish carefully in the oven and set the timer for twenty minutes.","She drank a glass of water."],"gapDistractors":[{"contextId":"u3_03_sprinkled_gap_1","answer":"sprinkled","wrong":["boiled","peeled","sliced"]},{"contextId":"u3_03_sprinkled_gap_2","answer":"sprinkled","wrong":["boiled","peeled","washed"]},{"contextId":"u3_03_sprinkled_gap_3","answer":"sprinkled","wrong":["boiled","peeled","weighed"]}],"spellingErrors":["sprinckled","sprinkeld","sprinkledd","sprinkelled","sprinklled","spinkled"],"wordFamilyForms":[{"form":"sprinkled","partOfSpeech":"verb","example":"Mum sprinkled a little cinnamon on top of the porridge.","pedagogicallyUseful":true},{"form":"sprinkle","partOfSpeech":"verb","example":"You can sprinkle grated cheese over the pasta just before serving.","pedagogicallyUseful":true,"altExample":"Remember to sprinkle sugar on the strawberries while they are still cold."},{"form":"sprinkling","partOfSpeech":"noun","example":"The soup was finished with a sprinkling of fresh parsley.","pedagogicallyUseful":true,"altExample":"A sprinkling of icing sugar made the cake look festive."}],"masteryPassages":[{"passageId":"u3_03_sprinkled_passage_1","contextId":"u3_03_sprinkled_gap_1","text":"The chef finished the dessert with a flourish. She ____ a handful of chopped nuts over the cream and then handed the plate to the waiter.","answer":"sprinkled"},{"passageId":"u3_03_sprinkled_passage_2","contextId":"u3_03_sprinkled_gap_2","text":"Salt is cheap and easy to use. The cook ____ a pinch of it onto the chips just before they were served.","answer":"sprinkled"}],"contextDependentParaphrases":[],"wrongParaphrases":["poured","mixed","wrapped"],"misleadingDistractors":["poured a large amount of liquid into something","cut something into very small pieces","removed something from a surface"]}]'::jsonb,'["sprinkle","sprinkling"]'::jsonb,'["sprinkled with","lightly sprinkled","sprinkled over"]'::jsonb,'live'),
('vocab_underestimate','underestimate','verb','to think that something is smaller, weaker or less important than it really is','[{"senseId":"underestimate_1","meaning":"to think that something is smaller, weaker or less important than it really is","acceptedParaphrases":["think too little of","rate too low"],"masteryContexts":[{"contextId":"u3_04_underestimate_meaning","text":"Most people underestimate the amount of salt in processed food, so they are shocked when they read the label.","meaning":"think something is less than it really is","wrongMeanings":["think something is more than it really is","know exactly what something is","forget what something is"]},{"contextId":"u3_04_underestimate_paraphrase","text":"It is easy to underestimate the time needed to cook a family meal from scratch, and many people finish dinner much later than planned.","meaning":"judge something to be smaller or easier than it is","wrongMeanings":["judge something to be larger or harder than it is","measure something with great care","plan something well in advance"]}],"situationDistractors":["He checked the recipe twice and set the timer for the exact cooking time.","The teacher praised the students for working out the cost so accurately.","The guide warned the group that the path would be long and difficult.","The manager counted the tables twice and wrote down the exact number.","The waiter knew exactly how long the soup would take because he had cooked it many times before.","He overcooked the rice."],"gapDistractors":[{"contextId":"u3_04_underestimate_gap_1","answer":"underestimate","wrong":["photograph","borrow","celebrate"]},{"contextId":"u3_04_underestimate_gap_2","answer":"underestimate","wrong":["invite","repair","photograph"]},{"contextId":"u3_04_underestimate_gap_3","answer":"underestimate","wrong":["carry","copy","paint"]}],"spellingErrors":["understimate","underestimete","underestamate","underrestimate","underestemate","undaestimate"],"wordFamilyForms":[{"form":"underestimate","partOfSpeech":"verb","example":"Never underestimate how tiring it is to work in a busy kitchen.","pedagogicallyUseful":true},{"form":"estimate","partOfSpeech":"noun","example":"The chef gave a rough estimate of how many guests would arrive.","pedagogicallyUseful":true,"altExample":"According to the first estimate, repairing the kitchen would cost about two thousand pounds."},{"form":"overestimate","partOfSpeech":"verb","example":"Beginners often overestimate how much food they can eat at a buffet.","pedagogicallyUseful":true,"altExample":"It is easy to overestimate how healthy a salad is when it is covered in dressing."}],"masteryPassages":[{"passageId":"u3_04_underestimate_passage_1","contextId":"u3_04_underestimate_gap_1","text":"Many people believe a salad is always healthy. They ____ how much oil and cream can be hidden in the dressing.","answer":"underestimate"},{"passageId":"u3_04_underestimate_passage_2","contextId":"u3_04_underestimate_gap_2","text":"Beginners should not ____ how long it takes to prepare a meal from fresh ingredients. Many of them are still cooking after two hours.","answer":"underestimate"}],"contextDependentParaphrases":[],"wrongParaphrases":["think too highly of","count again carefully","guess correctly"],"misleadingDistractors":["to guess the cost of something exactly","to make something larger than it was","to count something again carefully"],"grammarForms":{"base":"underestimate","thirdPerson":"underestimates","past":"underestimated","pastParticiple":"underestimated","ing":"underestimating"}}]'::jsonb,'["estimate","overestimate"]'::jsonb,'["seriously underestimate","never underestimate","easily underestimate"]'::jsonb,'live'),
('vocab_considerably','considerably','adverb','by a large amount','[{"senseId":"considerably_1","meaning":"by a large amount","acceptedParaphrases":["a great deal","much"],"masteryContexts":[{"contextId":"u3_05_considerably_meaning","text":"Prices at the school canteen have risen considerably since September.","meaning":"by a large amount","wrongMeanings":["by a small amount","at a very fast speed","for a long time"]},{"contextId":"u3_05_considerably_paraphrase","text":"The new menu is considerably healthier than the old one, with half the sugar and far more vegetables.","meaning":"to a much greater degree","wrongMeanings":["to a slightly greater degree","in a more careful way","at a much earlier time"]}],"situationDistractors":["The price of a school lunch went up by two pence last term.","The cafe is slightly cheaper than the one next door.","Prices stayed exactly the same for the whole year.","The soup was only a little saltier than yesterday, and nobody noticed the difference.","The price of the sandwich stayed the same, although the shop changed its name.","Prices rose by one penny."],"gapDistractors":[{"contextId":"u3_05_considerably_gap_1","answer":"considerably","wrong":["rarely","politely","silently"]},{"contextId":"u3_05_considerably_gap_2","answer":"considerably","wrong":["carefully","quietly","politely"]},{"contextId":"u3_05_considerably_gap_3","answer":"considerably","wrong":["carefully","quietly","happily"]}],"spellingErrors":["considerabley","considerrably","considerbly","consederably","considerablly","considerabily"],"masteryPassages":[{"passageId":"u3_05_considerably_passage_1","contextId":"u3_05_considerably_gap_1","text":"Ten years ago, a school lunch cost two pounds. Today the same meal costs ____ more, and many families find it hard to pay.","answer":"considerably"},{"passageId":"u3_05_considerably_passage_2","contextId":"u3_05_considerably_gap_2","text":"The new recipe has less than half the sugar of the old one. As a result, the cake tastes ____ less sweet.","answer":"considerably"}],"contextDependentParaphrases":[],"wrongParaphrases":["slightly","rarely","suddenly"],"misleadingDistractors":["by a very small amount","in a careful and polite way","for a short time"]}]'::jsonb,'[]'::jsonb,'["considerably more","considerably less","considerably higher"]'::jsonb,'live'),
('vocab_guaranteed','guaranteed','verb','promised that something will definitely happen or be true','[{"senseId":"guaranteed_1","meaning":"promised that something will definitely happen or be true","acceptedParaphrases":["promised","assured"],"masteryContexts":[{"contextId":"u3_06_guaranteed_meaning","text":"The company guaranteed a full refund if customers were not satisfied.","meaning":"promised for certain","wrongMeanings":["hoped for in secret","warned of in advance","guessed without any proof"]},{"contextId":"u3_06_guaranteed_paraphrase","text":"The shop guaranteed that all its eggs came from local farms, and showed the certificates to prove it.","meaning":"stated with complete certainty","wrongMeanings":["asked with great politeness","suggested with some doubt","denied with great anger"]}],"situationDistractors":["The manager said she would try to find out whether the fish was fresh.","The advert said the biscuits might be good for your health.","The waiter asked whether the customer wanted any more water.","The weather forecast said it might rain, but nobody was sure whether it would.","The cook hoped that the cake would rise, but she had never made it before.","The shop was closed."],"gapDistractors":[{"contextId":"u3_06_guaranteed_gap_1","answer":"guaranteed","wrong":["doubted","denied","regretted"]},{"contextId":"u3_06_guaranteed_gap_2","answer":"guaranteed","wrong":["feared","denied","doubted"]},{"contextId":"u3_06_guaranteed_gap_3","answer":"guaranteed","wrong":["regretted","denied","doubted"]}],"spellingErrors":["garanteed","guarenteed","guarantied","gaurenteed","guaranted","guarranteed"],"masteryPassages":[{"passageId":"u3_06_guaranteed_passage_1","contextId":"u3_06_guaranteed_gap_1","text":"The restaurant had a strict policy on quality. It ____ a full refund to any customer who was unhappy with a dish.","answer":"guaranteed"},{"passageId":"u3_06_guaranteed_passage_2","contextId":"u3_06_guaranteed_gap_2","text":"The label on the carton was clear. The farm ____ that the milk was fresh, and the date on every bottle proved it.","answer":"guaranteed"}],"contextDependentParaphrases":[],"wrongParaphrases":["doubted","predicted","hoped"],"misleadingDistractors":["warned that something might go wrong","asked whether something was true","refused to say whether something would happen"]}]'::jsonb,'[]'::jsonb,'["guaranteed refund","guaranteed delivery","guaranteed success"]'::jsonb,'live'),
('vocab_harmless','harmless','adjective','not able to cause damage or injury','[{"senseId":"harmless_1","meaning":"not able to cause damage or injury","acceptedParaphrases":["safe","not dangerous"],"masteryContexts":[{"contextId":"u3_07_harmless_meaning","text":"The doctor told her that the small insect in the salad was harmless.","meaning":"not able to hurt anyone","wrongMeanings":["likely to hurt someone","too small to notice","too old to eat"]},{"contextId":"u3_07_harmless_paraphrase","text":"Many people think that a little sugar is harmless, but too much can damage teeth.","meaning":"not causing any damage","wrongMeanings":["causing serious damage","costing a lot of money","needing a lot of care"]}],"situationDistractors":["The label warned that the product could make some people very ill.","The chemicals in the cleaning spray burned his skin.","The doctor advised her to avoid the food because it was full of bacteria.","The chemicals in the cleaning cupboard could burn skin if they were spilled.","The sign on the fence warned walkers that the dog was aggressive and might bite.","The mushroom was poisonous."],"gapDistractors":[{"contextId":"u3_07_harmless_gap_1","answer":"harmless","wrong":["poisonous","aggressive","venomous"]},{"contextId":"u3_07_harmless_gap_2","answer":"harmless","wrong":["dangerous","poisonous","illegal"]},{"contextId":"u3_07_harmless_gap_3","answer":"harmless","wrong":["dangerous","aggressive","deadly"]}],"spellingErrors":["harmles","harmlis","harmlessa","harmeless","hermless","harmlesss"],"wordFamilyForms":[{"form":"harmless","partOfSpeech":"adjective","example":"The tiny insect on the lettuce was completely harmless.","pedagogicallyUseful":true},{"form":"harm","partOfSpeech":"noun","example":"A single sweet will do no harm to a healthy child.","pedagogicallyUseful":true,"altExample":"The report found that fast food can cause serious harm when eaten every day."},{"form":"harmful","partOfSpeech":"adjective","example":"Smoking is harmful to the lungs.","pedagogicallyUseful":true,"altExample":"Some chemicals used in cleaning products are harmful if swallowed."}],"masteryPassages":[{"passageId":"u3_07_harmless_passage_1","contextId":"u3_07_harmless_gap_1","text":"Some people are afraid of spiders in the kitchen. However, the common house spider is completely ____ and may even catch other insects.","answer":"harmless"},{"passageId":"u3_07_harmless_passage_2","contextId":"u3_07_harmless_gap_2","text":"Eating a single biscuit now and then is fine. In small amounts, many sweet snacks are ____, but eating them all day is a different matter.","answer":"harmless"}],"contextDependentParaphrases":[],"wrongParaphrases":["poisonous","weak","tasteless"],"misleadingDistractors":["likely to cause serious illness","very expensive to produce","too small to be seen"]}]'::jsonb,'["harm","harmful"]'::jsonb,'["completely harmless","perfectly harmless","relatively harmless"]'::jsonb,'live'),
('vocab_pressure','pressure','noun','a strong feeling that you must do something because other people want or expect it','[{"senseId":"pressure_1","meaning":"a strong feeling that you must do something because other people want or expect it","acceptedParaphrases":["strong influence","forceful persuasion"],"masteryContexts":[{"contextId":"u3_08_pressure_meaning","text":"Students often feel pressure to buy the same snacks as their friends.","meaning":"a feeling that you must do something because others do","wrongMeanings":["a feeling of being hungry before a meal","a feeling that you want to be alone","a feeling that something is very good"]},{"contextId":"u3_08_pressure_paraphrase","text":"The advert put pressure on parents to buy the toy that came with the cereal.","meaning":"an attempt to make someone do something","wrongMeanings":["an offer to give someone a gift","a warning that someone may be hurt","a request for someone to wait"]}],"situationDistractors":["The doctor gave the boy a calm explanation and let him choose for himself.","The shopper looked at the prices, then decided to buy nothing at all.","Her friends said they did not mind what she ordered.","Nobody told Sam what to order, so he chose the dish he liked best.","The teacher explained the menu and then let the class decide what to cook.","She had an apple."],"gapDistractors":[{"contextId":"u3_08_pressure_gap_1","answer":"pressure","wrong":["permission","advice","pride"]},{"contextId":"u3_08_pressure_gap_2","answer":"pressure","wrong":["control","permission","pleasure"]},{"contextId":"u3_08_pressure_gap_3","answer":"pressure","wrong":["practice","pleasure","prize"]}],"spellingErrors":["presure","pressur","pressher","preshure","presssure","pressere"],"masteryPassages":[{"passageId":"u3_08_pressure_passage_1","contextId":"u3_08_pressure_gap_1","text":"Hana did not really like spicy food, but all her friends ordered the hottest curry. She felt ____ to do the same, so she ordered it too.","answer":"pressure"},{"passageId":"u3_08_pressure_passage_2","contextId":"u3_08_pressure_gap_2","text":"Advertisers aim their adverts at children. Parents often say they are under great ____ to buy the advertised snacks.","answer":"pressure"}],"contextDependentParaphrases":[],"wrongParaphrases":["strong flavour","large amount","quick answer"],"misleadingDistractors":["the weight of a heavy object pressing down","a bill for a service that has been used","the feeling of being very hungry"]}]'::jsonb,'[]'::jsonb,'["peer pressure","under pressure","great pressure"]'::jsonb,'live'),
('vocab_fooled','fooled','verb','tricked into believing something that is not true','[{"senseId":"fooled_1","meaning":"tricked into believing something that is not true","acceptedParaphrases":["tricked","deceived"],"masteryContexts":[{"contextId":"u3_09_fooled_meaning","text":"Do not be fooled by a label that says natural, because it does not always mean healthy.","meaning":"tricked into believing something false","wrongMeanings":["encouraged to try something new","warned about something dangerous","shown how something works"]},{"contextId":"u3_09_fooled_paraphrase","text":"He was fooled by the photo on the menu and expected a much bigger meal.","meaning":"given a false idea about something","wrongMeanings":["given a clear explanation of something","given a small present for something","given a polite warning about something"]}],"situationDistractors":["The customer read the label carefully and saw that the juice contained added sugar.","The waiter told the guests the truth about the ingredients.","The inspector found the hidden problem in the kitchen immediately.","The customer read the ingredients list and saw that the biscuits contained a lot of sugar.","The inspector noticed straight away that the date on the carton had been changed.","He was hungry."],"gapDistractors":[{"contextId":"u3_09_fooled_gap_1","answer":"fooled","wrong":["warned","invited","taught"]},{"contextId":"u3_09_fooled_gap_2","answer":"fooled","wrong":["praised","paid","taught"]},{"contextId":"u3_09_fooled_gap_3","answer":"fooled","wrong":["warned","taught","praised"]}],"spellingErrors":["fooleed","fouled","foold","fooldd","fuuled","fulled"],"masteryPassages":[{"passageId":"u3_09_fooled_passage_1","contextId":"u3_09_fooled_gap_1","text":"The photo made the burger look enormous. Customers who believed it were ____, because the real burger was half the size.","answer":"fooled"},{"passageId":"u3_09_fooled_passage_2","contextId":"u3_09_fooled_gap_2","text":"The label said “natural” in big green letters. Do not be ____ by this word, because many natural foods contain a lot of sugar.","answer":"fooled"}],"contextDependentParaphrases":[],"wrongParaphrases":["warned","surprised","persuaded"],"misleadingDistractors":["made to feel frightened","helped to understand the truth","asked to give an opinion"]}]'::jsonb,'[]'::jsonb,'["easily fooled","completely fooled","be fooled"]'::jsonb,'live'),
('vocab_majority','majority','noun','most of the people or things in a group','[{"senseId":"majority_1","meaning":"most of the people or things in a group","acceptedParaphrases":["the larger part","the greater part"],"masteryContexts":[{"contextId":"u3_10_majority_meaning","text":"The vast majority of customers chose the vegetarian option.","meaning":"most of a group","wrongMeanings":["a few of a group","all of a group","none of a group"]},{"contextId":"u3_10_majority_paraphrase","text":"In the vote, a majority of pupils wanted healthier food in the canteen, so the menu was changed.","meaning":"more than half of the people","wrongMeanings":["fewer than half of the people","exactly half of the people","all of the people"]}],"situationDistractors":["Only two students out of thirty chose the fish.","Every single guest asked for dessert.","A small number of customers complained about the noise.","Only a small number of pupils chose the fish, and most picked the pasta instead.","Every single guest at the wedding asked for a second helping of dessert.","Three people were absent."],"gapDistractors":[{"contextId":"u3_10_majority_gap_1","answer":"majority","wrong":["minority","average","total"]},{"contextId":"u3_10_majority_gap_2","answer":"majority","wrong":["minority","average","difference"]},{"contextId":"u3_10_majority_gap_3","answer":"majority","wrong":["minority","average","total"]}],"spellingErrors":["magority","majorety","majorrity","mejority","majoriti","majorty"],"masteryPassages":[{"passageId":"u3_10_majority_passage_1","contextId":"u3_10_majority_gap_1","text":"Thirty students voted on the new canteen menu. Twenty-two of them chose the vegetarian option, so the ____ got what they wanted.","answer":"majority"},{"passageId":"u3_10_majority_passage_2","contextId":"u3_10_majority_gap_2","text":"A few customers complained about the price. However, the great ____ left the restaurant happy.","answer":"majority"}],"contextDependentParaphrases":[],"wrongParaphrases":["a small group","the whole total","a few people"],"misleadingDistractors":["a small number of people in a group","every member of a group","the leader of a group"]}]'::jsonb,'[]'::jsonb,'["vast majority","great majority","large majority"]'::jsonb,'live')
