('u3_idea_participant',3,'idea_set','{"originalIdea":"Every participant in the baking contest must bring their own ingredients.","accurateParaphrases":["Everyone who takes part in the baking contest has to bring their own ingredients.","All the people entering the baking contest must provide their own ingredients.","Each person competing in the baking contest is required to bring ingredients themselves."],"meaningInvariants":[{"type":"quantity","value":"everyone brings their own ingredients"}],"distractors":[{"text":"Only the winner of the baking contest must bring their own ingredients.","misconceptionCategory":"quantity_change"},{"text":"Every spectator at the baking contest must bring their own ingredients.","misconceptionCategory":"meaning_confusion"},{"text":"Everyone who takes part in the baking contest receives free ingredients.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_participant"],"primaryEvidenceTargetId":"vocab_participant"}'::jsonb,'live'),
('u3_idea_outlet',3,'idea_set','{"originalIdea":"The company plans to open a new outlet in every major city.","accurateParaphrases":["The firm intends to open a new shop in each large city.","The company wants to set up another store in every big city.","A new branch will be opened by the company in every major city."],"meaningInvariants":[{"type":"quantity","value":"a new one in every major city"}],"distractors":[{"text":"The company plans to open a new shop in only one major city.","misconceptionCategory":"quantity_change"},{"text":"The company plans to close its shops in every major city.","misconceptionCategory":"polarity_change"},{"text":"The company plans to build a new factory in every major city.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_outlet"],"primaryEvidenceTargetId":"vocab_outlet"}'::jsonb,'live'),
('u3_idea_sprinkled',3,'idea_set','{"originalIdea":"The cook sprinkled a little cinnamon on the porridge.","accurateParaphrases":["The cook scattered a small amount of cinnamon over the porridge.","A small amount of cinnamon was shaken lightly onto the porridge by the cook.","The cook put just a pinch of cinnamon on top of the porridge."],"meaningInvariants":[{"type":"quantity","value":"a small amount"}],"distractors":[{"text":"The cook poured a lot of cinnamon into the porridge.","misconceptionCategory":"degree_change"},{"text":"The cook removed the cinnamon from the porridge.","misconceptionCategory":"omitted_information"},{"text":"The cook mixed a little cinnamon into the porridge and left it overnight.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_sprinkled"],"primaryEvidenceTargetId":"vocab_sprinkled"}'::jsonb,'live'),
('u3_idea_underestimate',3,'idea_set','{"originalIdea":"Many people underestimate how much sugar is in fruit juice.","accurateParaphrases":["Many people think there is less sugar in fruit juice than there really is.","Fruit juice contains more sugar than many people realise.","Many people do not realise how much sugar fruit juice contains."],"meaningInvariants":[{"type":"comparison","value":"more sugar than people think"}],"distractors":[{"text":"Many people think there is more sugar in fruit juice than there really is.","misconceptionCategory":"comparison_change"},{"text":"Many people know exactly how much sugar fruit juice contains.","misconceptionCategory":"polarity_change"},{"text":"Many people dislike the taste of sugar in fruit juice.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_underestimate"],"primaryEvidenceTargetId":"vocab_underestimate"}'::jsonb,'live'),
('u3_idea_considerably',3,'idea_set','{"originalIdea":"Fast-food prices have risen considerably over the last decade.","accurateParaphrases":["The cost of fast food has gone up a great deal in the past ten years.","Over the past ten years, fast-food prices have increased by a large amount.","Fast food is much more expensive than it was ten years ago."],"meaningInvariants":[{"type":"degree","value":"a large increase"}],"distractors":[{"text":"Fast-food prices have risen slightly over the last decade.","misconceptionCategory":"degree_change"},{"text":"Fast-food prices have fallen a great deal over the last decade.","misconceptionCategory":"polarity_change"},{"text":"Fast-food prices rose sharply last week.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_considerably"],"primaryEvidenceTargetId":"vocab_considerably"}'::jsonb,'live'),
('u3_idea_guaranteed',3,'idea_set','{"originalIdea":"The shop guaranteed that the strawberries would be fresh.","accurateParaphrases":["The shop promised for certain that the strawberries would be fresh.","The shop gave a firm promise that the strawberries would be fresh.","The shop assured us that the strawberries were certain to be fresh."],"meaningInvariants":[{"type":"degree","value":"complete certainty"}],"distractors":[{"text":"The shop hoped that the strawberries would be fresh.","misconceptionCategory":"degree_change"},{"text":"The shop warned that the strawberries might not be fresh.","misconceptionCategory":"polarity_change"},{"text":"The shop promised that the strawberries would be cheap.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_guaranteed"],"primaryEvidenceTargetId":"vocab_guaranteed"}'::jsonb,'live'),
('u3_idea_harmless',3,'idea_set','{"originalIdea":"Doctors say that the new sweetener is harmless in small amounts.","accurateParaphrases":["Doctors say that small amounts of the new sweetener are safe.","Doctors believe the new sweetener does no damage when eaten in small quantities.","According to doctors, small quantities of the new sweetener are not dangerous."],"meaningInvariants":[{"type":"quantity","value":"small amounts only"}],"distractors":[{"text":"Doctors say that the new sweetener is safe in any amount.","misconceptionCategory":"quantity_change"},{"text":"Doctors say that the new sweetener is dangerous even in small amounts.","misconceptionCategory":"polarity_change"},{"text":"Doctors say that the new sweetener tastes very sweet in small amounts.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_harmless"],"primaryEvidenceTargetId":"vocab_harmless"}'::jsonb,'live'),
('u3_idea_pressure',3,'idea_set','{"originalIdea":"Teenagers often feel pressure to try the latest food trends.","accurateParaphrases":["Teenagers often feel strongly pushed to try the latest food trends.","Teenagers frequently feel that they have to try the newest food trends.","Young people are often made to feel they must follow the newest food trends."],"meaningInvariants":[{"type":"cause_effect","value":"others push them to try food trends"}],"distractors":[{"text":"Teenagers rarely feel any need to try the latest food trends.","misconceptionCategory":"degree_change"},{"text":"Teenagers often feel excited about the latest food trends.","misconceptionCategory":"meaning_confusion"},{"text":"Teenagers often feel tired because they tried the latest food trends.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_pressure"],"primaryEvidenceTargetId":"vocab_pressure"}'::jsonb,'live'),
('u3_idea_fooled',3,'idea_set','{"originalIdea":"The customers were fooled by the fake discount sign.","accurateParaphrases":["The fake discount sign tricked the customers.","The customers were deceived by the false sign advertising lower prices.","The sign made the customers believe in a discount that did not exist."],"meaningInvariants":[{"type":"cause_effect","value":"the sign caused a false belief"}],"distractors":[{"text":"The customers noticed that the discount sign was fake.","misconceptionCategory":"polarity_change"},{"text":"The customers were pleased by the real discount sign.","misconceptionCategory":"meaning_confusion"},{"text":"The fake discount sign was put up by the customers.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_fooled"],"primaryEvidenceTargetId":"vocab_fooled"}'::jsonb,'live'),
('u3_idea_majority',3,'idea_set','{"originalIdea":"The majority of pupils chose pasta for the school party.","accurateParaphrases":["Most of the pupils chose pasta for the school party.","More than half the pupils picked pasta for the school party.","Pasta was the choice of most pupils for the school party."],"meaningInvariants":[{"type":"quantity","value":"most of the pupils"}],"distractors":[{"text":"A few pupils chose pasta for the school party.","misconceptionCategory":"quantity_change"},{"text":"Every pupil chose pasta for the school party.","misconceptionCategory":"quantity_change"},{"text":"Only the teachers chose pasta for the school party.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_majority"],"primaryEvidenceTargetId":"vocab_majority"}'::jsonb,'live'),
('u3_idea_inexpensive',3,'idea_set','{"originalIdea":"The cafe near school offers an inexpensive lunch for students.","accurateParaphrases":["The cafe near school sells a cheap lunch to students.","Students can buy lunch at the nearby cafe without spending much.","Lunch for students at the cafe near school does not cost much."],"meaningInvariants":[{"type":"degree","value":"a low price"}],"distractors":[{"text":"The cafe near school offers a free lunch for students.","misconceptionCategory":"degree_change"},{"text":"The cafe near school offers an expensive lunch for students.","misconceptionCategory":"polarity_change"},{"text":"The cafe near school offers lunch only to teachers.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_inexpensive"],"primaryEvidenceTargetId":"vocab_inexpensive"}'::jsonb,'live'),
('u3_idea_sodium',3,'idea_set','{"originalIdea":"Food labels show how much sodium a portion contains.","accurateParaphrases":["Food labels state the quantity of the mineral found in salt in each portion.","Packaging tells you how much of the mineral in salt is in a single serving.","Each label gives the amount of the mineral that salt contains for one portion."],"meaningInvariants":[{"type":"quantity","value":"amount per portion"}],"distractors":[{"text":"Food labels state the amount of vitamins in each portion.","misconceptionCategory":"meaning_confusion"},{"text":"Food labels state only the total weight of each portion.","misconceptionCategory":"omitted_information"},{"text":"Food labels state the amount of the mineral found in salt in the whole box.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_sodium"],"primaryEvidenceTargetId":"vocab_sodium"}'::jsonb,'live'),
('u3_idea_commercially',3,'idea_set','{"originalIdea":"The farm grows strawberries commercially and sells them to supermarkets.","accurateParaphrases":["The farm grows strawberries as a business and sells them to supermarkets.","The farm grows strawberries in order to sell them to supermarkets for profit.","Supermarkets buy the strawberries that the farm grows to sell."],"meaningInvariants":[{"type":"cause_effect","value":"grown in order to sell"}],"distractors":[{"text":"The farm grows strawberries only for the family and never sells them.","misconceptionCategory":"polarity_change"},{"text":"The farm grows strawberries and sells them only at the farm gate.","misconceptionCategory":"meaning_confusion"},{"text":"The farm buys strawberries from supermarkets.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_commercially"],"primaryEvidenceTargetId":"vocab_commercially"}'::jsonb,'live'),
('u3_idea_processed',3,'idea_set','{"originalIdea":"Many ready meals are made with processed meat, such as ham and sausages.","accurateParaphrases":["Many ready meals are made with meat prepared in factories, such as ham and sausages.","Ham and sausages, which are made in factories, are found in many ready meals.","Ready meals often contain factory-made meat such as ham and sausages."],"meaningInvariants":[{"type":"quantity","value":"many ready meals"}],"distractors":[{"text":"Few ready meals are made with meat prepared in factories.","misconceptionCategory":"quantity_change"},{"text":"Many ready meals are made with fresh meat from local farms.","misconceptionCategory":"meaning_confusion"},{"text":"Many ready meals are made without any meat.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_processed"],"primaryEvidenceTargetId":"vocab_processed"}'::jsonb,'live'),
('u3_idea_depression',3,'idea_set','{"originalIdea":"Students who suffer from depression may find it hard to concentrate in lessons.","accurateParaphrases":["Students who feel deep, long-lasting sadness may find it hard to concentrate in lessons.","Concentrating in lessons can be hard for students who have felt deeply sad for a long time.","It may be difficult for students with long-lasting sadness to focus in lessons."],"meaningInvariants":[{"type":"degree","value":"long-lasting deep sadness"}],"distractors":[{"text":"Students who feel nervous before a test may find it hard to concentrate in lessons.","misconceptionCategory":"meaning_confusion"},{"text":"Students who feel deeply sad for a long time find it easy to concentrate in lessons.","misconceptionCategory":"polarity_change"},{"text":"Students who feel long-lasting sadness always fail their lessons.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_depression"],"primaryEvidenceTargetId":"vocab_depression"}'::jsonb,'live'),
('u3_idea_overweight',3,'idea_set','{"originalIdea":"About a third of the pupils in the survey were overweight.","accurateParaphrases":["About a third of the pupils in the survey weighed more than is healthy for their height.","Roughly a third of the pupils in the survey were heavier than is healthy for their height.","One in three pupils in the survey was above a healthy weight."],"meaningInvariants":[{"type":"quantity","value":"about a third"}],"distractors":[{"text":"About two thirds of the pupils in the survey weighed more than is healthy for their height.","misconceptionCategory":"quantity_change"},{"text":"About a third of the pupils in the survey weighed less than is healthy for their height.","misconceptionCategory":"comparison_change"},{"text":"About a third of the pupils in the survey were taller than the others.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_overweight"],"primaryEvidenceTargetId":"vocab_overweight"}'::jsonb,'live'),
('u3_idea_unwell',3,'idea_set','{"originalIdea":"The chef went home early because he felt unwell.","accurateParaphrases":["The chef left early because he was ill.","Feeling ill, the chef went home early.","The chef went home before the end of the day as he was not feeling well."],"meaningInvariants":[{"type":"cause_effect","value":"left because ill"}],"distractors":[{"text":"The chef went home early because he was angry with the manager.","misconceptionCategory":"cause_effect_change"},{"text":"The chef stayed late even though he felt ill.","misconceptionCategory":"time_change"},{"text":"The chef felt ill because he went home early.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_unwell"],"primaryEvidenceTargetId":"vocab_unwell"}'::jsonb,'live'),
('u3_idea_ingredients',3,'idea_set','{"originalIdea":"The cook checked the ingredients before starting the recipe.","accurateParaphrases":["The cook looked at the foods needed for the recipe before beginning it.","Before beginning the recipe, the cook made sure of the foods that go into it.","The cook examined what the recipe needed before starting to cook."],"meaningInvariants":[{"type":"time","value":"before starting"}],"distractors":[{"text":"The cook checked the foods needed for the recipe after finishing it.","misconceptionCategory":"time_change"},{"text":"The cook bought new pans before starting the recipe.","misconceptionCategory":"meaning_confusion"},{"text":"The cook skipped checking and started the recipe at once.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_ingredients"],"primaryEvidenceTargetId":"vocab_ingredients"}'::jsonb,'live'),
('u3_idea_nutritious',3,'idea_set','{"originalIdea":"The canteen serves a nutritious meal every day.","accurateParaphrases":["The canteen serves a healthy meal every day.","Every day the canteen provides a meal that is good for the body.","Each day the canteen offers food that gives the body what it needs."],"meaningInvariants":[{"type":"time","value":"every day"}],"distractors":[{"text":"The canteen serves a healthy meal only on Fridays.","misconceptionCategory":"time_change"},{"text":"The canteen serves a sugary meal every day.","misconceptionCategory":"meaning_confusion"},{"text":"The canteen sells a healthy meal every day at a high price.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_nutritious"],"primaryEvidenceTargetId":"vocab_nutritious"}'::jsonb,'live'),
('u3_idea_moderation',3,'idea_set','{"originalIdea":"The teacher suggested eating sweets in moderation.","accurateParaphrases":["The teacher suggested eating sweets in sensible amounts, not too much.","The teacher advised having only a reasonable amount of sweets.","Sweets, said the teacher, should be eaten but not in large quantities."],"meaningInvariants":[{"type":"degree","value":"a limited amount"}],"distractors":[{"text":"The teacher suggested never eating sweets at all.","misconceptionCategory":"degree_change"},{"text":"The teacher suggested eating as many sweets as possible.","misconceptionCategory":"degree_change"},{"text":"The teacher suggested giving sweets to friends.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_moderation"],"primaryEvidenceTargetId":"vocab_moderation"}'::jsonb,'live'),
('u3_idea_deceive',3,'idea_set','{"originalIdea":"Some adverts deceive children by making sweets look healthy.","accurateParaphrases":["Some adverts mislead children by making sweets seem healthy.","Certain adverts trick children into thinking that sweets are healthy.","By making sweets look healthy, some adverts give children a false idea."],"meaningInvariants":[{"type":"cause_effect","value":"adverts cause a false belief"}],"distractors":[{"text":"Some adverts warn children that sweets are not healthy.","misconceptionCategory":"polarity_change"},{"text":"Some adverts persuade children to buy healthy fruit.","misconceptionCategory":"meaning_confusion"},{"text":"Some adverts show children how to make sweets.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_deceive"],"primaryEvidenceTargetId":"vocab_deceive"}'::jsonb,'live'),
('u3_idea_advertisement',3,'idea_set','{"originalIdea":"The advertisement for the new pizza appears on television every evening.","accurateParaphrases":["The advert for the new pizza is shown on television every evening.","Every evening, television shows an advert for the new pizza.","An advert for the new pizza comes on the television each evening."],"meaningInvariants":[{"type":"time","value":"every evening"}],"distractors":[{"text":"The advert for the new pizza appears on television only on Sundays.","misconceptionCategory":"time_change"},{"text":"The review of the new pizza appears on television every evening.","misconceptionCategory":"meaning_confusion"},{"text":"The advert for the new pizza appeared on television once last year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_advertisement"],"primaryEvidenceTargetId":"vocab_advertisement"}'::jsonb,'live'),
('u3_idea_variety',3,'idea_set','{"originalIdea":"The market offers a wide variety of fresh fruit.","accurateParaphrases":["The market sells a large range of fresh fruit.","Shoppers at the market can choose from many different kinds of fresh fruit.","Many kinds of fresh fruit are available at the market."],"meaningInvariants":[{"type":"quantity","value":"many kinds"}],"distractors":[{"text":"The market sells only one kind of fresh fruit.","misconceptionCategory":"quantity_change"},{"text":"The market sells a large amount of the same fresh fruit.","misconceptionCategory":"meaning_confusion"},{"text":"The market offers fresh fruit at a low price.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_variety"],"primaryEvidenceTargetId":"vocab_variety"}'::jsonb,'live'),
('u3_idea_portion',3,'idea_set','{"originalIdea":"The restaurant gives customers a large portion of rice with every curry.","accurateParaphrases":["The restaurant serves a big helping of rice with each curry.","With every curry, the restaurant gives customers a generous serving of rice.","Each curry comes with a big amount of rice for one person."],"meaningInvariants":[{"type":"degree","value":"large"}],"distractors":[{"text":"The restaurant serves a tiny helping of rice with each curry.","misconceptionCategory":"degree_change"},{"text":"The restaurant serves a big helping of rice with only some curries.","misconceptionCategory":"quantity_change"},{"text":"The restaurant sells large bags of rice with every curry.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_portion"],"primaryEvidenceTargetId":"vocab_portion"}'::jsonb,'live'),
('u3_idea_purchase',3,'idea_set','{"originalIdea":"Please keep the receipt for every purchase you make in the shop.","accurateParaphrases":["Please keep the receipt for everything you buy in the shop.","Make sure you hold on to the receipt for each item you buy in the shop.","The receipt for each thing bought in the shop should be kept."],"meaningInvariants":[{"type":"quantity","value":"every item"}],"distractors":[{"text":"Please keep the receipt only for the most expensive thing you buy in the shop.","misconceptionCategory":"quantity_change"},{"text":"Please throw away the receipt for everything you buy in the shop.","misconceptionCategory":"polarity_change"},{"text":"Please keep the receipt for every item you sell in the shop.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_purchase"],"primaryEvidenceTargetId":"vocab_purchase"}'::jsonb,'live'),
('u3_idea_takeaway',3,'idea_set','{"originalIdea":"We usually order a takeaway on Friday evenings.","accurateParaphrases":["We usually order a meal to eat at home on Friday evenings.","On Friday evenings we normally buy hot food from a restaurant to eat at home.","Friday evening is when we typically get a restaurant meal to take home."],"meaningInvariants":[{"type":"time","value":"Friday evenings"}],"distractors":[{"text":"We usually order a meal to eat at home on Sunday mornings.","misconceptionCategory":"time_change"},{"text":"We usually cook a meal at home on Friday evenings.","misconceptionCategory":"polarity_change"},{"text":"We usually eat at a restaurant table on Friday evenings.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_takeaway"],"primaryEvidenceTargetId":"vocab_takeaway"}'::jsonb,'live'),
('u3_idea_barbecue',3,'idea_set','{"originalIdea":"Our neighbours hold a barbecue in the garden every summer.","accurateParaphrases":["Every summer, our neighbours have an outdoor meal cooked over a fire in their garden.","Each summer our neighbours throw a garden party where food is grilled.","Our neighbours cook food outdoors at a party in their garden each summer."],"meaningInvariants":[{"type":"time","value":"every summer"}],"distractors":[{"text":"Our neighbours hold an outdoor cooking party in their garden every winter.","misconceptionCategory":"time_change"},{"text":"Our neighbours hold a formal dinner indoors every summer.","misconceptionCategory":"meaning_confusion"},{"text":"Our neighbours hold an outdoor cooking party in their garden every summer and charge guests money.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_barbecue"],"primaryEvidenceTargetId":"vocab_barbecue"}'::jsonb,'live'),
('u3_idea_saturated',3,'idea_set','{"originalIdea":"Butter contains more saturated fat than olive oil.","accurateParaphrases":["Butter contains more of the type of fat found in fatty meat than olive oil does.","Compared with butter, olive oil contains less of the type of fat found in cheese and fatty meat.","Butter has a higher amount of the type of fat found in cheese and fatty meat than olive oil has."],"meaningInvariants":[{"type":"comparison","value":"butter has more"}],"distractors":[{"text":"Olive oil contains more of the type of fat found in cheese and fatty meat than butter does.","misconceptionCategory":"comparison_change"},{"text":"Butter contains less of the type of fat found in cheese and fatty meat than olive oil does.","misconceptionCategory":"comparison_change"},{"text":"Butter costs more than olive oil.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_saturated"],"primaryEvidenceTargetId":"vocab_saturated"}'::jsonb,'live'),
('u3_idea_convenient',3,'idea_set','{"originalIdea":"Ready meals are convenient for people who work long hours.","accurateParaphrases":["Ready meals are handy for people who work long hours.","People who work long hours find ready meals easy and time-saving.","For those with long working hours, ready meals save time and effort."],"meaningInvariants":[{"type":"cause_effect","value":"saves time and effort"}],"distractors":[{"text":"Ready meals are cheap for people who work long hours.","misconceptionCategory":"meaning_confusion"},{"text":"Ready meals are unpopular with people who work long hours.","misconceptionCategory":"polarity_change"},{"text":"Ready meals are healthy for people who work long hours.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_convenient"],"primaryEvidenceTargetId":"vocab_convenient"}'::jsonb,'live'),
('u3_idea_extensive',3,'idea_set','{"originalIdea":"The restaurant has an extensive menu with over a hundred dishes.","accurateParaphrases":["The restaurant has a wide-ranging menu with over a hundred dishes.","There are more than a hundred dishes on the restaurant’s very large menu.","The restaurant’s menu is very large and lists over a hundred dishes."],"meaningInvariants":[{"type":"quantity","value":"over a hundred dishes"}],"distractors":[{"text":"The restaurant has a short menu with fewer than ten dishes.","misconceptionCategory":"quantity_change"},{"text":"The restaurant has a menu with over a hundred dishes, all of them free.","misconceptionCategory":"added_information"},{"text":"The restaurant has an expensive menu with only a few dishes.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_extensive"],"primaryEvidenceTargetId":"vocab_extensive"}'::jsonb,'live'),
('u3_idea_fashionable',3,'idea_set','{"originalIdea":"Vegan burgers have become fashionable among teenagers in the city.","accurateParaphrases":["Vegan burgers have become trendy with teenagers in the city.","Teenagers in the city now think vegan burgers are in style.","Among teenagers in the city, vegan burgers have turned into a popular trend."],"meaningInvariants":[{"type":"time","value":"has become popular recently"}],"distractors":[{"text":"Vegan burgers have become cheaper for teenagers in the city.","misconceptionCategory":"meaning_confusion"},{"text":"Vegan burgers have always been popular among teenagers in the city.","misconceptionCategory":"time_change"},{"text":"Vegan burgers have become unpopular among teenagers in the city.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_fashionable"],"primaryEvidenceTargetId":"vocab_fashionable"}'::jsonb,'live'),
('u3_idea_satisfying',3,'idea_set','{"originalIdea":"The hot soup was satisfying after the long walk in the cold.","accurateParaphrases":["The hot soup was very pleasing after the long, cold walk.","After the long walk in the cold, the hot soup was just what we wanted.","The hot soup gave us a pleasant feeling after the cold walk."],"meaningInvariants":[{"type":"time","value":"after the long walk"}],"distractors":[{"text":"The hot soup was disappointing after the long walk in the cold.","misconceptionCategory":"polarity_change"},{"text":"The hot soup was served before the long walk in the cold.","misconceptionCategory":"time_change"},{"text":"The hot soup was too hot to eat after the long walk in the cold.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_satisfying"],"primaryEvidenceTargetId":"vocab_satisfying"}'::jsonb,'live'),
('u3_idea_reasonable',3,'idea_set','{"originalIdea":"Most customers think the prices at this cafe are reasonable.","accurateParaphrases":["Most customers believe the prices at this cafe are fair.","Most diners consider that this cafe charges fair prices.","Customers generally find the cafe’s prices fair."],"meaningInvariants":[{"type":"quantity","value":"most customers"}],"distractors":[{"text":"A few customers think the prices at this cafe are fair.","misconceptionCategory":"quantity_change"},{"text":"Most customers think the prices at this cafe are too high.","misconceptionCategory":"polarity_change"},{"text":"Most customers think the portions at this cafe are large.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_reasonable_3"],"primaryEvidenceTargetId":"vocab_reasonable_3"}'::jsonb,'live'),
('u3_idea_disappointed',3,'idea_set','{"originalIdea":"Many diners were disappointed that the restaurant had no vegetarian dishes.","accurateParaphrases":["Many diners felt let down because the restaurant had no vegetarian dishes.","Many diners were unhappy that the restaurant offered no vegetarian dishes.","The lack of vegetarian dishes at the restaurant left many diners let down."],"meaningInvariants":[{"type":"cause_effect","value":"no vegetarian dishes caused unhappiness"}],"distractors":[{"text":"Many diners were delighted that the restaurant had no vegetarian dishes.","misconceptionCategory":"polarity_change"},{"text":"Many diners were unhappy that the restaurant had no meat dishes.","misconceptionCategory":"cause_effect_change"},{"text":"A few diners felt let down that the restaurant had no vegetarian dishes.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_disappointed"],"primaryEvidenceTargetId":"vocab_disappointed"}'::jsonb,'live'),
('u3_idea_inconvenient',3,'idea_set','{"originalIdea":"The restaurant’s location is inconvenient for people without a car.","accurateParaphrases":["The restaurant’s location is not suitable for people without a car.","People without a car find the restaurant’s location troublesome.","Reaching the restaurant is difficult for people who do not have a car."],"meaningInvariants":[{"type":"polarity","value":"difficult for people without a car"}],"distractors":[{"text":"The restaurant’s location is ideal for people without a car.","misconceptionCategory":"polarity_change"},{"text":"The restaurant’s location is expensive for people without a car.","misconceptionCategory":"meaning_confusion"},{"text":"The restaurant’s location is not suitable for people with a car.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_inconvenient"],"primaryEvidenceTargetId":"vocab_inconvenient"}'::jsonb,'live'),
('u3_idea_excellent',3,'idea_set','{"originalIdea":"The reviews describe the service at the new restaurant as excellent.","accurateParaphrases":["The reviews describe the service at the new restaurant as outstanding.","According to the reviews, the new restaurant’s service is of a very high standard.","Reviewers say the service at the new restaurant is much better than most."],"meaningInvariants":[{"type":"degree","value":"a very high standard"}],"distractors":[{"text":"The reviews describe the service at the new restaurant as average.","misconceptionCategory":"degree_change"},{"text":"The reviews describe the service at the new restaurant as terrible.","misconceptionCategory":"polarity_change"},{"text":"The reviews describe the prices at the new restaurant as outstanding.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_excellent"],"primaryEvidenceTargetId":"vocab_excellent"}'::jsonb,'live'),
('u3_idea_polite',3,'idea_set','{"originalIdea":"The waiter was polite to every customer, even during the busy lunch hour.","accurateParaphrases":["The waiter showed good manners to every customer, even during the busy lunch hour.","Even at the busy lunch hour, the waiter was courteous to each customer.","Every customer was treated with respect by the waiter, even during the busy lunch hour."],"meaningInvariants":[{"type":"quantity","value":"every customer"}],"distractors":[{"text":"The waiter showed good manners only to regular customers, even during the busy lunch hour.","misconceptionCategory":"quantity_change"},{"text":"The waiter was rude to every customer, even during the busy lunch hour.","misconceptionCategory":"polarity_change"},{"text":"The waiter was quick with every customer, even during the busy lunch hour.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_polite"],"primaryEvidenceTargetId":"vocab_polite"}'::jsonb,'live'),
('u3_idea_helpful',3,'idea_set','{"originalIdea":"The staff were helpful and answered all our questions about the menu.","accurateParaphrases":["The staff were willing to help and answered all our questions about the menu.","The staff gave useful answers to all our questions about the menu.","All our questions about the menu were answered by friendly, supportive staff."],"meaningInvariants":[{"type":"quantity","value":"all questions"}],"distractors":[{"text":"The staff were willing to help but answered only some of our questions about the menu.","misconceptionCategory":"quantity_change"},{"text":"The staff refused to answer our questions about the menu.","misconceptionCategory":"polarity_change"},{"text":"The staff were friendly and gave us a free dessert.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_helpful"],"primaryEvidenceTargetId":"vocab_helpful"}'::jsonb,'live'),
('u3_idea_recommendation',3,'idea_set','{"originalIdea":"We chose the cafe on the recommendation of our teacher.","accurateParaphrases":["We chose the cafe because our teacher suggested it.","Our teacher suggested the cafe, so we went there.","The cafe was our choice after advice from our teacher."],"meaningInvariants":[{"type":"cause_effect","value":"the teacher suggested it"}],"distractors":[{"text":"We chose the cafe because our teacher complained about it.","misconceptionCategory":"cause_effect_change"},{"text":"We chose the cafe, so our teacher suggested it.","misconceptionCategory":"cause_effect_change"},{"text":"We chose the cafe because our teacher paid for it.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_recommendation"],"primaryEvidenceTargetId":"vocab_recommendation"}'::jsonb,'live'),
('u3_idea_informative',3,'idea_set','{"originalIdea":"The leaflet about healthy eating was informative and easy to read.","accurateParaphrases":["The leaflet about healthy eating gave useful facts and was easy to read.","The healthy eating leaflet was full of facts and easy to read.","Readers learned a lot from the clear leaflet about healthy eating."],"meaningInvariants":[{"type":"degree","value":"full of useful facts"}],"distractors":[{"text":"The leaflet about healthy eating was funny and easy to read.","misconceptionCategory":"meaning_confusion"},{"text":"The leaflet about healthy eating gave no facts and was easy to read.","misconceptionCategory":"polarity_change"},{"text":"The leaflet about healthy eating gave useful facts but was hard to read.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_informative"],"primaryEvidenceTargetId":"vocab_informative"}'::jsonb,'live'),
('u3_idea_reflection',3,'idea_set','{"originalIdea":"After some reflection, the owner decided to change the menu.","accurateParaphrases":["After thinking about it carefully, the owner decided to change the menu.","The owner thought carefully and then decided to change the menu.","Once she had thought it over, the owner decided to change the menu."],"meaningInvariants":[{"type":"time","value":"after careful thought"}],"distractors":[{"text":"Before thinking about it, the owner decided to change the menu.","misconceptionCategory":"time_change"},{"text":"After some thinking, the owner decided to keep the menu the same.","misconceptionCategory":"polarity_change"},{"text":"After a short argument, the owner decided to change the menu.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_reflection"],"primaryEvidenceTargetId":"vocab_reflection"}'::jsonb,'live'),
('u3_idea_organiser',3,'idea_set','{"originalIdea":"The organiser of the food fair booked forty stalls for the weekend.","accurateParaphrases":["The person who arranged the food fair booked forty stalls for the weekend.","The food fair’s planner booked forty stalls for the weekend.","The person in charge of planning the food fair booked forty stalls for the weekend."],"meaningInvariants":[{"type":"quantity","value":"forty stalls"}],"distractors":[{"text":"A visitor to the food fair booked forty stalls for the weekend.","misconceptionCategory":"meaning_confusion"},{"text":"The person who arranged the food fair booked only four stalls for the weekend.","misconceptionCategory":"quantity_change"},{"text":"The person who arranged the food fair cancelled forty stalls for the weekend.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_organiser"],"primaryEvidenceTargetId":"vocab_organiser"}'::jsonb,'live'),
('u3_idea_presenter',3,'idea_set','{"originalIdea":"The presenter of the programme introduced three guest chefs.","accurateParaphrases":["The host of the programme introduced three guest chefs.","The programme’s host introduced three guest chefs.","The person leading the programme introduced three guest chefs."],"meaningInvariants":[{"type":"quantity","value":"three guest chefs"}],"distractors":[{"text":"A viewer of the programme introduced three guest chefs.","misconceptionCategory":"meaning_confusion"},{"text":"The host of the programme introduced only one guest chef.","misconceptionCategory":"quantity_change"},{"text":"The host of the programme introduced three guest chefs and then cooked a meal.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_presenter"],"primaryEvidenceTargetId":"vocab_presenter"}'::jsonb,'live'),
('u3_idea_evaluate',3,'idea_set','{"originalIdea":"Judges evaluate each dish carefully before giving a score.","accurateParaphrases":["Judges assess each dish carefully before giving a score.","Before giving a score, judges carefully judge the quality of each dish.","Judges give each dish a careful assessment before scoring it."],"meaningInvariants":[{"type":"time","value":"before giving a score"}],"distractors":[{"text":"Judges give a score to each dish before looking at it carefully.","misconceptionCategory":"time_change"},{"text":"Judges ignore each dish and simply give a score.","misconceptionCategory":"polarity_change"},{"text":"Judges cook each dish carefully before giving a score.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_evaluate"],"primaryEvidenceTargetId":"vocab_evaluate"}'::jsonb,'live'),
('u3_idea_consume',3,'idea_set','{"originalIdea":"Visitors to the festival consume thousands of snacks every day.","accurateParaphrases":["Visitors to the festival eat thousands of snacks every day.","Every day, thousands of snacks are eaten by visitors to the festival.","Festival visitors get through thousands of snacks every day."],"meaningInvariants":[{"type":"quantity","value":"thousands of snacks"}],"distractors":[{"text":"Visitors to the festival eat a few snacks every day.","misconceptionCategory":"quantity_change"},{"text":"Visitors to the festival sell thousands of snacks every day.","misconceptionCategory":"meaning_confusion"},{"text":"Visitors to the festival eat thousands of snacks every week.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_consume"],"primaryEvidenceTargetId":"vocab_consume"}'::jsonb,'live'),
('u3_idea_balanced',3,'idea_set','{"originalIdea":"The school lunch is balanced, with vegetables, protein and rice.","accurateParaphrases":["The school lunch has the right mix of vegetables, protein and rice.","The school lunch contains vegetables, protein and rice in the right amounts.","In the school lunch, vegetables, protein and rice are well proportioned."],"meaningInvariants":[{"type":"degree","value":"right proportions"}],"distractors":[{"text":"The school lunch contains too much rice and almost no vegetables or protein.","misconceptionCategory":"degree_change"},{"text":"The school lunch is cheap, with vegetables, protein and rice.","misconceptionCategory":"meaning_confusion"},{"text":"The school lunch has the right mix of vegetables and rice.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_balanced"],"primaryEvidenceTargetId":"vocab_balanced"}'::jsonb,'live'),
('u3_idea_calorie',3,'idea_set','{"originalIdea":"The nutrition label gives the calorie value of one portion.","accurateParaphrases":["The nutrition label gives the energy value of one portion.","The label states how much food energy one portion contains.","The food energy in one portion is shown on the nutrition label."],"meaningInvariants":[{"type":"quantity","value":"one portion"}],"distractors":[{"text":"The nutrition label gives the energy value of the whole packet.","misconceptionCategory":"quantity_change"},{"text":"The nutrition label gives the price of one portion.","misconceptionCategory":"meaning_confusion"},{"text":"The nutrition label gives the energy value of one portion and the cooking time.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_calorie"],"primaryEvidenceTargetId":"vocab_calorie"}'::jsonb,'live'),
('u3_idea_hygienic',3,'idea_set','{"originalIdea":"The inspector said that the kitchen was hygienic.","accurateParaphrases":["The inspector said that the kitchen was clean and free from germs.","According to the inspector, the kitchen was clean and safe from germs.","The inspector found that the kitchen was free from dirt and germs."],"meaningInvariants":[{"type":"polarity","value":"the kitchen was clean and safe"}],"distractors":[{"text":"The inspector said that the kitchen was dirty and unsafe.","misconceptionCategory":"polarity_change"},{"text":"The inspector said that the kitchen was tidy and large.","misconceptionCategory":"meaning_confusion"},{"text":"The inspector said that the kitchen was clean and that the staff were friendly.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_hygienic"],"primaryEvidenceTargetId":"vocab_hygienic"}'::jsonb,'live'),
('u3_idea_appetising',3,'idea_set','{"originalIdea":"The smell of the soup was appetising, so we ordered two bowls.","accurateParaphrases":["The smell of the soup was so tempting that we ordered two bowls.","We ordered two bowls because the smell of the soup was mouth-watering.","The mouth-watering smell of the soup made us order two bowls."],"meaningInvariants":[{"type":"cause_effect","value":"the smell led to the order"}],"distractors":[{"text":"We ordered two bowls, so the smell of the soup was tempting.","misconceptionCategory":"cause_effect_change"},{"text":"The smell of the soup was unpleasant, so we ordered two bowls.","misconceptionCategory":"polarity_change"},{"text":"The smell of the soup was tempting, so we ordered one bowl.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_appetising"],"primaryEvidenceTargetId":"vocab_appetising"}'::jsonb,'live'),
('u3_idea_cuisine',3,'idea_set','{"originalIdea":"Many tourists visit the region to enjoy its local cuisine.","accurateParaphrases":["Many tourists visit the region to enjoy its local style of cooking.","Many tourists travel to the region to enjoy its traditional cooking.","The region’s local cooking attracts many tourists."],"meaningInvariants":[{"type":"quantity","value":"many tourists"}],"distractors":[{"text":"A few tourists visit the region to enjoy its local style of cooking.","misconceptionCategory":"quantity_change"},{"text":"Many tourists avoid the region because of its local style of cooking.","misconceptionCategory":"polarity_change"},{"text":"Many tourists visit the region to enjoy its local weather.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_cuisine"],"primaryEvidenceTargetId":"vocab_cuisine"}'::jsonb,'live'),
('u3_writing_precision_participant_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “person who takes part” with a more precise Unit 3 word or phrase.","sourceText":"Each person who takes part in the quiz receives a small prize.","acceptedAnswers":["participant"],"distractors":["spectator","organiser","sponsor"],"linkedVocabularyIds":["vocab_participant"],"primaryEvidenceTargetId":"vocab_participant"}'::jsonb,'live'),
('u3_writing_precision_participant_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “people taking part” with a more precise Unit 3 word or phrase.","sourceText":"The charity thanked all the people taking part in the sponsored walk.","acceptedAnswers":["participants"],"distractors":["spectators","judges","reporters"],"linkedVocabularyIds":["vocab_participant"],"primaryEvidenceTargetId":"vocab_participant"}'::jsonb,'live'),
('u3_writing_precision_outlet_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “place that sells food” with a more precise Unit 3 word or phrase.","sourceText":"The town has a new place that sells food right next to the bus station.","acceptedAnswers":["food outlet","outlet"],"distractors":["food factory","food warehouse","food farm"],"linkedVocabularyIds":["vocab_outlet"],"primaryEvidenceTargetId":"vocab_outlet"}'::jsonb,'live'),
