('u3_writing_precision_sprinkled_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “scattered” with a more precise Unit 3 word or phrase.","sourceText":"The waiter scattered salt over the chips before bringing them to our table.","acceptedAnswers":["sprinkled"],"distractors":["boiled","sliced","weighed"],"linkedVocabularyIds":["vocab_sprinkled"],"primaryEvidenceTargetId":"vocab_sprinkled"}'::jsonb,'live'),
('u3_writing_precision_sprinkled_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “spread a little” with a more precise Unit 3 word or phrase.","sourceText":"Dad spread a little icing sugar over the pancakes just before breakfast.","acceptedAnswers":["sprinkled"],"distractors":["baked","peeled","weighed"],"linkedVocabularyIds":["vocab_sprinkled"],"primaryEvidenceTargetId":"vocab_sprinkled"}'::jsonb,'live'),
('u3_writing_precision_underestimate_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “think too little of” with a more precise Unit 3 word or phrase.","sourceText":"Never think too little of the effect that sugary drinks have on your teeth.","acceptedAnswers":["underestimate"],"distractors":["borrow","repair","celebrate"],"linkedVocabularyIds":["vocab_underestimate"],"primaryEvidenceTargetId":"vocab_underestimate"}'::jsonb,'live'),
('u3_writing_precision_underestimate_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “do not realise the size of” with a more precise Unit 3 word or phrase.","sourceText":"Many people do not realise the size of the problem of food waste.","acceptedAnswers":["underestimate"],"distractors":["solve","cause","report"],"linkedVocabularyIds":["vocab_underestimate"],"primaryEvidenceTargetId":"vocab_underestimate"}'::jsonb,'live'),
('u3_writing_precision_considerably_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “a lot” with a more precise Unit 3 word or phrase.","sourceText":"Restaurant meals cost a lot more than home cooking.","acceptedAnswers":["considerably"],"distractors":["slightly","rarely","suddenly"],"linkedVocabularyIds":["vocab_considerably"],"primaryEvidenceTargetId":"vocab_considerably"}'::jsonb,'live'),
('u3_writing_precision_considerably_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “by a large amount” with a more precise Unit 3 word or phrase.","sourceText":"The school has reduced its sugar use by a large amount since the new rules began.","acceptedAnswers":["considerably"],"distractors":["slightly","hardly","quietly"],"linkedVocabularyIds":["vocab_considerably"],"primaryEvidenceTargetId":"vocab_considerably"}'::jsonb,'live'),
('u3_writing_precision_guaranteed_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “definitely promised” with a more precise Unit 3 word or phrase.","sourceText":"The shop definitely promised that the fish would be fresh on delivery.","acceptedAnswers":["guaranteed"],"distractors":["hoped","doubted","wondered"],"linkedVocabularyIds":["vocab_guaranteed"],"primaryEvidenceTargetId":"vocab_guaranteed"}'::jsonb,'live'),
('u3_writing_precision_guaranteed_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “made a firm promise” with a more precise Unit 3 word or phrase.","sourceText":"The supermarket made a firm promise that the eggs came from free-range hens.","acceptedAnswers":["guaranteed"],"distractors":["wondered","hoped","forgot"],"linkedVocabularyIds":["vocab_guaranteed"],"primaryEvidenceTargetId":"vocab_guaranteed"}'::jsonb,'live'),
('u3_writing_precision_harmless_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “not dangerous” with a more precise Unit 3 word or phrase.","sourceText":"The doctor said the tiny insect in the salad was not dangerous.","acceptedAnswers":["harmless"],"distractors":["poisonous","harmful","deadly"],"linkedVocabularyIds":["vocab_harmless"],"primaryEvidenceTargetId":"vocab_harmless"}'::jsonb,'live'),
('u3_writing_precision_harmless_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “safe” with a more precise Unit 3 word or phrase.","sourceText":"Most people think one sweet a day is completely safe, though dentists disagree.","acceptedAnswers":["harmless"],"distractors":["poisonous","harmful","dangerous"],"linkedVocabularyIds":["vocab_harmless"],"primaryEvidenceTargetId":"vocab_harmless"}'::jsonb,'live'),
('u3_writing_precision_pressure_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “strong influence” with a more precise Unit 3 word or phrase.","sourceText":"Teenagers often choose snacks because of strong influence from their friends.","acceptedAnswers":["pressure"],"distractors":["permission","payment","punishment"],"linkedVocabularyIds":["vocab_pressure"],"primaryEvidenceTargetId":"vocab_pressure"}'::jsonb,'live'),
('u3_writing_precision_pressure_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “forceful persuasion” with a more precise Unit 3 word or phrase.","sourceText":"Parents sometimes give in to forceful persuasion from children who want sweets.","acceptedAnswers":["pressure"],"distractors":["permission","kindness","punishment"],"linkedVocabularyIds":["vocab_pressure"],"primaryEvidenceTargetId":"vocab_pressure"}'::jsonb,'live'),
('u3_writing_precision_fooled_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “tricked” with a more precise Unit 3 word or phrase.","sourceText":"Some shoppers are tricked by labels that say “natural” or “fresh”.","acceptedAnswers":["fooled"],"distractors":["paid","taught","praised"],"linkedVocabularyIds":["vocab_fooled"],"primaryEvidenceTargetId":"vocab_fooled"}'::jsonb,'live'),
('u3_writing_precision_fooled_b',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “deceived” with a more precise Unit 3 word or phrase.","sourceText":"Customers were deceived by the advert showing a burger twice the real size.","acceptedAnswers":["fooled"],"distractors":["bored","invited","thanked"],"linkedVocabularyIds":["vocab_fooled"],"primaryEvidenceTargetId":"vocab_fooled"}'::jsonb,'live'),
('u3_writing_precision_majority_a',3,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “most” with a more precise Unit 3 word or phrase.","sourceText":"In our school, most of the pupils have lunch in the canteen.","acceptedAnswers":["the majority","a majority"],"distractors":["the minority","the average","the total"],"linkedVocabularyIds":["vocab_majority"],"primaryEvidenceTargetId":"vocab_majority"}'::jsonb,'live'),
